    uploadStorageObject: {
        parameters: {
            query?: never;
            header?: {
                /** @description Upload session ID (for completing resumable uploads) */
                "X-Upload-Session"?: string;
                /** @description Set to "true" to complete a resumable upload session */
                "X-Upload-Complete"?: "true";
            };
            path: {
                /** @description Storage bucket name */
                bucketName: components["parameters"]["BucketName"];
                /** @description Object path within bucket */
                path: string;
            };
            cookie?: never;
        };
        requestBody: {
            content: {
                "multipart/form-data": {
                    /**
                     * Format: binary
                     * @description File to upload (simple upload)
                     */
                    file: string;
                };
                "application/json": components["schemas"]["CreateUploadSessionRequest"];
            };
        };
        responses: {
            /** @description Resumable upload completed (when X-Upload-Complete=true) */
            200: {
                headers: {
                    [name: string]: unknown;
                };
                content: {
                    "application/json": components["schemas"]["CompleteUploadSessionResponse"];
                };
            };
            /** @description File uploaded or session created */
            201: {
                headers: {
                    [name: string]: unknown;
                };
                content: {
                    "application/json": components["schemas"]["StorageObject"] | components["schemas"]["CreateUploadSessionResponse"];
                };
            };
            /**
             * @description Bad request. This can occur when:
             *     - MIME type is not in the bucket's allowed_mime_types list
             *     - File exceeds the bucket's configured file_size_limit
             *     - File exceeds the global maximum upload size (5GB)
             *     - Invalid request body or missing required fields
             */
            400: {
                headers: {
                    [name: string]: unknown;
                };
                content?: never;
            };
            /** @description Access denied by storage policy */
            403: {
                headers: {
                    [name: string]: unknown;
                };
                content?: never;
            };
            /**
             * @description File size exceeds plan-based limits. This occurs when:
             *     - File exceeds the plan-based maximum file size (FREE or PRO tier)
             *     - Upload would exceed the project's total storage quota
             */
            413: {
                headers: {
                    [name: string]: unknown;
                };
                content?: never;
            };
            429: components["responses"]["BandwidthCapExceeded"];
        };
    };
